  visibleRatio(){const d=this.frame.contentDocument,w=this.frame.contentWindow;if(this.isPage()){const r=this.frame.getBoundingClientRect(),max=Math.max(1,d.body.scrollHeight-Math.max(1,innerHeight-100));return clamp((100-r.top)/max,0,1,0)}return clamp(w.scrollY/Math.max(1,d.documentElement.scrollHeight-w.innerHeight),0,1,0)},
  onScroll(){if(!this.ready||$('#readerPanel').hidden||$('#workspace').hidden)return;this.placeDrawer();this.placeOptions();if(this.selection)this.placeSelection();if(Date.now()<(this.suppressUntil||0)||this.suspendPosition)return;this.hasScrolled=true;const y=this.isPage()?scrollY:this.frame.contentWindow.scrollY,delta=y-(this.lastScroll||0);if(Math.abs(delta)>10){this.toolbar(delta<0);this.lastScroll=y}this.lastLocation=this.currentLocation();clearTimeout(this.saveTimer);this.saveTimer=setTimeout(()=>this.savePosition(),280);},
  shortChapterEnd(){if(!this.ready||this.index!==this.chapters.length-1||Date.now()<(this.suppressUntil||0))return;const d=this.frame.contentDocument,w=this.frame.contentWindow;if(d.body.scrollHeight<=(this.isPage()?innerHeight-100:w.innerHeight)+2){this.hasScrolled=true;this.savePosition();updateBook(this.bookId,b=>({...b,finished:true,readingProgress:1,readerPosition:{...b.readerPosition,progress:1}})).then(()=>this.progressText()).catch(serious)}},
  toolbar(visible){const el=$('.reader-controls');if(!el)return;const pinned=this.selection||!$('#readerOptions')?.hidden||!$('#readerDrawer')?.hidden||el.contains(document.activeElement);el.classList.toggle('toolbar-hidden',!visible&&!pinned)},
  showToolbar(){this.toolbar(true)},
  setupTools(){
    const drawer=$('#readerDrawer');$('#readerDrawerToggle').onclick=()=>{drawer.hidden=!drawer.hidden;$('#readerDrawerToggle').setAttribute('aria-expanded',!drawer.hidden);this.placeDrawer();this.showToolbar();if(!drawer.hidden)$('#closeReaderDrawer').focus({preventScroll:true})};$('#closeReaderDrawer').onclick=()=>this.closeDrawer();
    for(const [id,annotations] of [['contentsTab',false],['annotationsTab',true]])$('#'+id).onclick=()=>{for(const [tab,value] of [['contentsTab',!annotations],['annotationsTab',annotations]])$('#'+tab).setAttribute('aria-selected',value);$('#contentsList').hidden=annotations;$('#annotationsPanel').hidden=!annotations};
    $('#contentsList').innerHTML=this.chapters.map((c,i)=>`<button data-chapter="${i}">${escapeHTML(c.title)}</button>`).join('');$('#contentsList').onclick=e=>{const button=e.target.closest('[data-chapter]');if(button)this.show(Number(button.dataset.chapter))};
    $('#readerSettingsToggle').onclick=()=>{const options=$('#readerOptions');options.hidden=!options.hidden;$('#readerSettingsToggle').setAttribute('aria-expanded',!options.hidden);this.placeOptions();this.showToolbar()};
    $('#selectionTools').insertAdjacentHTML('beforeend','<button id="removeSelectionHighlight">Remove Highlight</button><button id="dismissSelection" aria-label="Dismiss annotation tools">×</button>');$('#dismissSelection').onclick=()=>this.dismiss();$('#removeSelectionHighlight').onclick=async()=>{const h=this.selectedHighlight();if(!h)return;await updateBook(this.bookId,b=>ArchiveModel.deleteHighlight(b,h.id));this.paint();this.listHighlights();Board.refresh();this.placeSelection()};
    if(!$('#passageNote'))document.body.insertAdjacentHTML('beforeend','<dialog id="passageNote"><form method="dialog"><h2>Passage Note</h2><label>Note<textarea id="passageNoteText" rows="6"></textarea></label><div class="dialog-actions"><button value="cancel">Cancel</button><button class="primary" value="save">Save note</button></div></form></dialog>');
  },
  closeDrawer(focus=true){if(!$('#readerDrawer'))return;$('#readerDrawer').hidden=true;$('#readerDrawerToggle').setAttribute('aria-expanded','false');if(focus)$('#readerDrawerToggle').focus({preventScroll:true})},
  placeDrawer(){const drawer=$('#readerDrawer');if(!drawer||drawer.hidden)return;const r=$('#readerPanel').getBoundingClientRect();drawer.style.setProperty('--drawer-left',Math.max(0,r.left)+'px');drawer.style.setProperty('--drawer-top',Math.max(48,r.top+46)+'px');drawer.style.setProperty('--drawer-width',Math.min(340,r.width)+'px')},
  placeOptions(){const panel=$('#readerOptions'),toolbar=$('.reader-controls');if(!panel||panel.hidden||!toolbar)return;const r=toolbar.getBoundingClientRect();panel.style.position='fixed';panel.style.top=Math.max(48,Math.min(innerHeight-panel.offsetHeight-8,r.bottom+4))+'px';panel.style.left=Math.max(8,r.right-panel.offsetWidth)+'px';panel.style.right='auto'},
  selectedHighlight(){const s=this.selection;return s&&(books.find(b=>b.id===this.bookId)?.highlights||[]).find(h=>h.href===s.href&&h.start===s.start&&h.end===s.end&&h.text===s.text)},
  placeSelection(){
    if(!this.selection)return;this.showToolbar();const tools=$('#selectionTools'),h=this.selectedHighlight();tools.hidden=false;if(h)$('#highlightColor').value=h.color;$('#removeSelectionHighlight').hidden=!h;$('#annotateSelection').textContent=h?.note?'Edit Note':'Add Note';$('#relinkSelection').hidden=!this.relinkCardId;
    const range=this.rangeAt(this.selection.start,this.selection.end),rect=range?.getBoundingClientRect(),fr=this.frame.getBoundingClientRect();const left=fr.left+(rect?.left||20),top=fr.top+(rect?.bottom||20)+8;tools.style.left=Math.max(8,Math.min(innerWidth-tools.offsetWidth-8,left))+'px';tools.style.top=Math.max(8,Math.min(innerHeight-tools.offsetHeight-8,top))+'px';
  },
